    if(travel){$('mapOverlay').classList.add('open');$('mapOverlay').setAttribute('aria-hidden','false');state.turn--;moveTime(-15);toast('Escolha um destino no mapa.');return;}
    if(talk){let npc=getNpc(lower);meet(npc);let check=roll('wit',11);let greet=npc.trust>1?'O reconhecimento suaviza o olhar.':npc.trust<0?'A mão se aproxima do cinto, sem chegar a tocá-lo.':'A pessoa mede suas palavras antes de responder.';
      if(/ameaç/.test(lower)){npc.trust=(npc.trust||0)-1;state.rep='Temido';outcome='A ameaça fica no ar. A confiança diminui.';result=`<strong>${esc(npc.name)}</strong> endurece o semblante. “Em Brumafria, quem ameaça acaba ouvindo passos atrás de si.” ${greet}`;}
      else if(/negoci|persuad|convenc/.test(lower)){if(check.success){npc.trust=(npc.trust||0)+1;state.gold+=3;outcome=`Teste de astúcia: ${check.total} — sucesso`;result=`<strong>${esc(npc.name)}</strong> considera sua proposta. Um acordo modesto é firmado; você recebe 3 moedas. “Não confunda um trato com amizade.”`; }else{outcome=`Teste de astúcia: ${check.total} — sucesso parcial`;result=`<strong>${esc(npc.name)}</strong> não aceita o acordo, mas revela uma pista: ${esc(r.event)}`;}}
      else if(/pergunt|ouço|escut|rumor|conversa/.test(lower)){result=`<strong>${esc(npc.name)}</strong> limpa as mãos no avental. “${esc(r.event)}” ${greet}`;outcome='Um rumor passa a fazer parte da sua memória.';if(!state.flags[`rumor-${r.id}`]){state.flags[`rumor-${r.id}`]=true;state.quests.push({id:`rumor-${r.id}`,title:`Ecos de ${r.city}`,giver:npc.name,kind:`RUMOR · ${r.name.toUpperCase()}`,desc:r.event,state:'Disponível',progress:0});}}
      else{result=`Você se aproxima de <strong>${esc(npc.name)}</strong>. ${esc(npc.look)} ${greet} “O que procura por estas bandas?”`;outcome='O encontro foi registrado no códice.';}
      npc.memory.push(`${state.day}/${timeText()}: ${text.slice(0,100)}`);if(npc.memory.length>15)npc.memory.shift();
    }else if(attack){let check=roll('might',12);state.stamina=Math.max(0,state.stamina-3);if(check.success){state.hp=Math.max(1,state.hp-(Math.random()<.25?2:0));const xp=18;const leveled=gainXP(xp);outcome=`Teste de vigor: ${check.total} — vitória · +${xp} XP${leveled?' · nível aumentado!':''}`;result=`Seu movimento rompe o silêncio. A ameaça recua, deixando para trás ${Math.random()<.5?'uma presa de osso polido':'um punhado de moedas antigas'}. Você não sabe quem mais ouviu o combate.`;if(Math.random()<.5){state.items.push('Presa de osso');}else state.gold+=4;state.rep='Nome em circulação';}else{state.hp=Math.max(1,state.hp-4);outcome=`Teste de vigor: ${check.total} — revés · -4 vitalidade`;result=`A criatura lê seu movimento antes que você termine. Você recua com um corte superficial; o ruído se perde na névoa, mas não por muito tempo.`;}
    }else if(rest){if(/compr|vendo|vender/.test(lower)){if(state.gold>=5){state.gold-=5;state.items.push('Ração de viagem');result='O mercador pesa cinco moedas na palma e lhe entrega uma ração embrulhada em pano encerado.';outcome='−5 ouro · +1 ração de viagem';}else{result='O mercador olha para sua bolsa vazia. “Volte quando suas moedas fizerem mais barulho.”';outcome='Você não tem ouro suficiente.';}}else{state.hp=Math.min(state.maxHp,state.hp+7);state.stamina=state.maxStamina;result='Você encontra abrigo por algumas horas. O frio continua, mas suas mãos param de tremer e o fôlego retorna.';outcome='Vitalidade e fôlego recuperados.';}}
    else if(investigate||stealth){const check=roll('wit',stealth?14:11);if(check.success){state.xp+=12;let found;if(!state.secrets.includes(r.id)&&Math.random()<.48){state.secrets.push(r.id);found=`${r.secret}`;outcome=`Teste de astúcia: ${check.total} — descoberta · +12 XP`; }else{const loot=['Ervas secas','Moeda antiga','Fragmento de mapa','Fivela de prata'];found=`Você encontra ${loot[Math.floor(Math.random()*loot.length)]} entre os vestígios.`;state.items.push(loot[Math.floor(Math.random()*loot.length)]);outcome=`Teste de astúcia: ${check.total} — sucesso · +12 XP`;}
        result=`${found} ${stealth?'Você não deixa rastros óbvios.':'A paisagem parece guardar mais do que mostra.'}`;const leveled=gainXP(12);if(leveled)outcome+=' · nível aumentado!';if(!state.quests.some(q=>q.id==='bells'&&q.state==='Concluída')&&(/capela|sino|cripta/.test(lower))){const q=state.quests.find(x=>x.id==='bells');if(q){q.state='Concluída';q.note='Você encontrou marcas frescas junto à cripta. A origem do sino ainda é um mistério.';state.gold+=9;outcome+=' · +9 ouro';}}}
      else{result=`A névoa muda de forma enquanto você procura. Uma sensação de estar sendo observado interrompe a busca. Você volta de mãos vazias, mas com uma impressão: ${esc(r.event)}`;outcome=`Teste de astúcia: ${check.total} — nada encontrado.`;}}
    else{const rollResult=roll('wit',12);if(rollResult.success){state.xp+=6;const leveled=gainXP(6);outcome=`O mundo responde à sua maneira · +6 XP${leveled?' · nível aumentado!':''}`;result=`Você age por conta própria. ${esc(r.event)} Algo na situação muda quando sua presença se torna impossível de ignorar.`;}else{outcome='O mundo não cede facilmente.';result=`Você tenta agir, mas ${r.name} não se dobra à sua vontade. ${esc(r.event)} Ainda há outros caminhos — ou outra forma de tentar.`;}}
    const safeText=esc(text).replace(/\n/g,' ');addEntry(`<strong>${esc(state.name)}:</strong> “${safeText}”<br>${result}`,{result});recordEvent(`${state.name}: ${text.slice(0,100)} — ${outcome}`);updateMemory();render();$('actionInput').value='';$('actionInput').focus();
  }
