  $('actionForm').addEventListener('submit',e=>{e.preventDefault();action($('actionInput').value);});
  $('actionInput').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('actionForm').requestSubmit();}});
  $('openMap').onclick=()=>{$('mapOverlay').classList.add('open');$('mapOverlay').setAttribute('aria-hidden','false');buildMap();};
  document.querySelectorAll('.close-map').forEach(b=>b.onclick=closeMap);$('mapOverlay').addEventListener('click',e=>{if(e.target===$('mapOverlay'))closeMap();});
